const fs = require('fs');

const input = fs.readFileSync(0, 'utf8').trim();
if (!input) process.exit(0);
const n = parseInt(input, 10);

const INF = BigInt("1" + "0".repeat(30)); // sufficiently large

// dp[i][j] = minimal weight to triangulate polygon from i to j (1-based)
const dp = Array.from({ length: n + 1 }, () => Array(n + 1).fill(0n));

for (let len = 3; len <= n; len++) {
    for (let i = 1; i + len - 1 <= n; i++) {
        const j = i + len - 1;
        let best = INF;
        for (let k = i + 1; k < j; k++) {
            const cost = dp[i][k] + dp[k][j] + BigInt(i) * BigInt(k) * BigInt(j);
            if (cost < best) best = cost;
        }
        dp[i][j] = best;
    }
}

